<script setup>
import { computed, onUnmounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { tr } from '../../../utils/i18n'
import { createK8sWorkloadBundle, updateK8sResourceYAML } from '../../../api/k8s'
import { confirmRiskOperation } from '../../../composables/useRiskConfirm'
import { clone, manifestYAML, newWorkload, newContainer, prepareWorkload, podTemplate, workloadManifest, validateWorkload, buildAccessResources, updateImpact } from '../../../utils/k8s-workload-editor'
import ContainerEditor from './K8sContainerEditor.vue'
import AffinityEditor from './K8sAffinityEditor.vue'
import JsonField from './K8sJsonField.vue'
import Rows from './K8sObjectRows.vue'
import MapEditor from './K8sMapEditor.vue'
const props = defineProps({page:Object})
const targetCluster = clone(props.page.cluster)
let disposed=false
onUnmounted(() => {disposed=true})
const editing = ref(Boolean(props.page.workloadEditorResource))
const original = props.page.workloadEditorResource ? prepareWorkload(props.page.workloadEditorResource) : null
const draft = ref(original ? clone(original) : newWorkload('Deployment', props.page.namespaceFilter !== '__all__' ? props.page.namespaceFilter : props.page.namespaces[0]?.name || ''))
const active = ref('containers'), activeContainer = ref('0'), busy = ref(false), error = ref(''), results = ref(null), validated = ref('')
const jsonValidity = reactive({})
const access = reactive({enabled:!editing.value,name:'',type:'ClusterIP',ports:[{name:'http',port:80,targetPort:8080,protocol:'TCP'}],ingress:false,className:'',rules:[],tls:[]})
const partial = computed(() => Object.values(results.value || {}).some(v => ['created','reused'].includes(v?.status)))
const frozen = computed(() => partial.value || (editing.value && draft.value.kind === 'Job'))
const template = computed(() => podTemplate(draft.value)), pod = computed(() => template.value.spec)
const jobSpec = computed(() => draft.value.kind === 'CronJob' ? draft.value.spec.jobTemplate.spec : draft.value.spec)
const manifest = computed(() => workloadManifest(draft.value, editing.value))
const snapshot = computed(() => {
  const resources = buildAccessResources(manifest.value, access)
  return {workloadYaml:JSON.stringify(manifest.value,null,2),serviceYaml:resources.service ? JSON.stringify(resources.service,null,2) : '',ingressYaml:resources.ingress ? JSON.stringify(resources.ingress,null,2) : ''}
})
const preview = computed(() => Object.values(snapshot.value).filter(Boolean).map(value => manifestYAML(JSON.parse(value))).join('\n---\n'))
const options = list => (list || []).filter(item => item.namespace === draft.value.metadata.namespace)
const configMaps = computed(() => options(props.page.configMaps)), secrets = computed(() => options(props.page.secrets)), pvcs = computed(() => options(props.page.storages).filter(i => ['PVC','PersistentVolumeClaim'].includes(i.kind)))
const volumes = computed(() => [...(pod.value.volumes || []),...(draft.value.spec.volumeClaimTemplates || []).map(v => ({name:v.metadata.name}))])
const sections = [{key:'containers',label:'容器配置'},{key:'storage',label:'存储挂载'},{key:'scheduling',label:'调度策略'},{key:'affinity',label:'亲和性'},{key:'strategy',label:'更新与任务策略'},{key:'security',label:'Pod 安全配置'},{key:'access',label:'访问设置'},{key:'review',label:'信息确认'}]
function changeKind(kind) { draft.value = newWorkload(kind,draft.value.metadata.namespace); activeContainer.value='0'; results.value=null; Object.keys(jsonValidity).forEach(key => delete jsonValidity[key]) }
function valid(key, value) { jsonValidity[key] = value }
function check() {
  if (Object.values(jsonValidity).includes(false)) throw Error(tr('请修正 JSON 配置错误'))
  const message = validateWorkload(manifest.value)
  if (message) throw Error(tr(message))
  if (!editing.value && access.ingress && (!access.enabled || !access.rules.length)) throw Error(tr('Ingress 必须关联 Service 并至少配置一条路由'))
  if (!editing.value && access.enabled && !access.ports.length) throw Error(tr('Service 至少需要一个端口'))
}
function payload() { return {clusterId:targetCluster.id,namespace:draft.value.metadata.namespace,workloadType:draft.value.kind,name:draft.value.metadata.name,resourceType:'workload',yaml:snapshot.value.workloadYaml,...snapshot.value,skipWorkload:['created','reused'].includes(results.value?.workload?.status),skipService:['created','reused'].includes(results.value?.service?.status)} }
async function validate() {
  error.value=''; check()
  const data = editing.value ? await updateK8sResourceYAML({...payload(),dryRun:true}) : await createK8sWorkloadBundle({...payload(),dryRun:true})
  if (data.complete === false) throw Error(Object.values(data).filter(v => v?.error).map(v => v.error).join('\n'))
  validated.value=preview.value
  return data
}
async function validateOnly() { busy.value=true; try { await validate(); ElMessage.success(tr('服务端校验通过')) } catch(e) { error.value=e.message } finally { busy.value=false } }
async function submit() {
  busy.value=true; error.value=''
  try {
    await validate()
    if(disposed) return
    await confirmRiskOperation({operation:tr(editing.value ? '更新工作负载' : '创建工作负载'),targetSummary:`${targetCluster.name} / ${draft.value.metadata.namespace} / ${draft.value.metadata.name}`,production:['prod','production','生产','线上'].includes(targetCluster.env),targetCount:1})
    if(disposed) return
    const data = editing.value ? await updateK8sResourceYAML({...payload(),dryRun:false}) : await createK8sWorkloadBundle({...payload(),dryRun:false})
    results.value=data
    if (data.complete === false) { active.value='review'; error.value=tr('部分资源创建失败，已成功的资源会保留；请重试失败项'); return }
    ElMessage.success(tr(editing.value ? '工作负载已更新' : '工作负载及关联资源已创建'))
    props.page.workloadCreateVisible=false
    await props.page.refreshCurrentClusterData()
  } catch(e) { if (!['cancel','close'].includes(e)) {error.value=e.message || String(e);active.value='review'} } finally {busy.value=false}
}
function addVolume() { (pod.value.volumes ||= []).push({name:`volume-${(pod.value.volumes?.length || 0)+1}`,emptyDir:{}}) }
function volumeType(v) { return ['persistentVolumeClaim','configMap','secret','emptyDir','hostPath','projected','csi','nfs'].find(type => v[type]) || 'other' }
function setVolumeType(v,type) { for (const key of Object.keys(v)) if(key !== 'name') delete v[key]; v[type] = type === 'persistentVolumeClaim' ? {claimName:''} : type === 'configMap' ? {name:''} : type === 'secret' ? {secretName:''} : type === 'hostPath' ? {path:'',type:'DirectoryOrCreate'} : {} }
function addRule() { access.rules.push({host:'',http:{paths:[{path:'/',pathType:'Prefix',backend:{service:{name:access.name || draft.value.metadata.name,port:{number:access.ports[0]?.port || 80}}}}]}}) }
function cloneJob() { editing.value=false; for(const key of ['uid','resourceVersion','creationTimestamp']) delete draft.value.metadata[key]; draft.value.metadata.name=''; delete draft.value.spec.selector; for(const key of ['controller-uid','batch.kubernetes.io/controller-uid','job-name','batch.kubernetes.io/job-name']) delete template.value.metadata.labels?.[key]; access.enabled=false }
const strategyKey = computed(() => draft.value.kind === 'Deployment' ? 'strategy' : 'updateStrategy')
function setStrategy(type) { const key=strategyKey.value; const previous=draft.value.spec[key] || {}; draft.value.spec[key]={...previous,type}; if(type !== 'RollingUpdate') delete draft.value.spec[key].rollingUpdate; else draft.value.spec[key].rollingUpdate ||= {} }
function diffRows(before, after, path='') {
  if (JSON.stringify(before) === JSON.stringify(after)) return []
  if(Array.isArray(before) && Array.isArray(after) && before.length === after.length) return before.flatMap((item,index) => diffRows(item,after[index],`${path}/${item?.name || index}`))
  if (before && after && !Array.isArray(before) && !Array.isArray(after) && typeof before === 'object' && typeof after === 'object') return [...new Set([...Object.keys(before),...Object.keys(after)])].flatMap(key => diffRows(before[key],after[key],`${path}/${key}`))
  return [{path,before:JSON.stringify(before) ?? '—',after:JSON.stringify(after) ?? '—'}]
}
const changes = computed(() => editing.value ? diffRows(workloadManifest(original,true),manifest.value) : [])
</script>

<template>
  <section class="kwe-page" v-loading="busy">
    <header class="kwe-heading"><div><el-button link @click="page.workloadCreateVisible=false">← {{ tr('返回工作负载') }}</el-button><h2>{{ tr(editing ? '配置工作负载' : '创建工作负载') }}</h2><p>{{ page.cluster?.name }} <span>/</span> {{ draft.kind }} <span>/</span> {{ draft.metadata.namespace || '—' }}</p></div><el-tag effect="plain">{{ tr(editing ? '编辑配置' : '新建资源') }}</el-tag></header>
    <el-alert v-if="partial" :title="tr('部分资源已经创建，当前配置已锁定；重试将跳过成功项')" type="warning" :closable="false" />
    <el-alert v-if="editing" :title="tr(updateImpact(draft))" type="info" :closable="false" />
    <section class="kwe-basic"><el-form label-position="top" :disabled="frozen"><div class="kwe-grid"><el-form-item :label="tr('工作负载类型')"><el-select :model-value="draft.kind" :disabled="editing" @change="changeKind"><el-option v-for="kind in ['Deployment','StatefulSet','DaemonSet','Job','CronJob']" :key="kind" :value="kind" /></el-select></el-form-item><el-form-item :label="tr('命名空间')" required><el-select v-model="draft.metadata.namespace" :disabled="editing" filterable><el-option v-for="ns in page.namespaces" :key="ns.name" :value="ns.name" /></el-select></el-form-item><el-form-item :label="tr('名称')" required><el-input v-model.trim="draft.metadata.name" :disabled="editing" maxlength="63" /></el-form-item><el-form-item v-if="['Deployment','StatefulSet'].includes(draft.kind)" :label="tr('实例数量')"><el-input-number v-model="draft.spec.replicas" :min="0" /></el-form-item></div><el-collapse><el-collapse-item :title="tr('标签与注解')"><JsonField v-model="draft.metadata.labels" :label="tr('资源标签（JSON）')" @validity="valid('labels',$event)" /><JsonField v-model="draft.metadata.annotations" :label="tr('资源注解（JSON）')" @validity="valid('annotations',$event)" /><JsonField v-model="template.metadata.labels" :label="tr('Pod 标签（JSON）')" @validity="valid('pod-labels',$event)" /><JsonField v-model="template.metadata.annotations" :label="tr('Pod 注解（JSON）')" @validity="valid('pod-annotations',$event)" /></el-collapse-item></el-collapse></el-form><el-button v-if="editing && draft.kind === 'Job'" @click="cloneJob">{{ tr('另存为新任务') }}</el-button></section>
    <div class="kwe-body"><nav class="kwe-navigation"><button v-for="section in sections.filter(s => !editing || s.key !== 'access')" :key="section.key" :class="{active:active===section.key}" @click="active=section.key">{{ tr(section.label) }}</button></nav><main class="kwe-content">
      <section v-show="active==='containers'"><div class="kwe-section-title"><h3>{{ tr('容器配置') }}</h3><el-button :disabled="frozen" @click="pod.containers.push(newContainer(`container-${pod.containers.length+1}`));activeContainer=String(pod.containers.length-1)">+ {{ tr('业务容器') }}</el-button><el-button :disabled="frozen" @click="(pod.initContainers ||= []).push(newContainer(`init-${(pod.initContainers?.length || 0)+1}`))">+ {{ tr('初始化容器') }}</el-button></div><el-tabs v-model="activeContainer"><el-tab-pane v-for="(c,i) in pod.containers" :key="i" :name="String(i)" :label="c.name || `container-${i+1}`"><ContainerEditor :container="c" :volumes="volumes" :config-maps="configMaps" :secrets="secrets" :disabled="frozen" @validity="(key,v) => valid(`container-${i}-${key}`,v)" /><el-button v-if="pod.containers.length>1" type="danger" plain :disabled="frozen" @click="pod.containers.splice(i,1);activeContainer='0'">{{ tr('删除容器') }}</el-button></el-tab-pane><el-tab-pane v-for="(c,i) in pod.initContainers" :key="`init-${i}`" :name="`init-${i}`" :label="`Init · ${c.name}`"><ContainerEditor :container="c" :volumes="volumes" :config-maps="configMaps" :secrets="secrets" :disabled="frozen" init @validity="(key,v) => valid(`init-${i}-${key}`,v)" /><el-button :disabled="frozen" type="danger" plain @click="pod.initContainers.splice(i,1);activeContainer='0'">{{ tr('删除容器') }}</el-button></el-tab-pane></el-tabs></section>
      <section v-show="active==='storage'"><h3>{{ tr('存储挂载') }}</h3><p class="kwe-hint">{{ tr('先定义存储卷，再到容器配置中选择挂载路径') }}</p><el-form label-position="top" :disabled="frozen"><div v-for="(v,i) in pod.volumes" :key="i" class="kwe-card"><div class="kwe-grid"><el-form-item :label="tr('卷名称')"><el-input v-model="v.name" /></el-form-item><el-form-item :label="tr('类型')"><el-select :model-value="volumeType(v)" @change="setVolumeType(v,$event)"><el-option v-for="type in ['persistentVolumeClaim','configMap','secret','emptyDir','hostPath','projected','csi','nfs']" :key="type" :value="type" /></el-select></el-form-item></div><el-select v-if="v.persistentVolumeClaim" v-model="v.persistentVolumeClaim.claimName" filterable :placeholder="tr('选择 PVC')"><el-option v-for="pvc in pvcs" :key="pvc.name" :value="pvc.name" /></el-select><el-select v-if="v.configMap" v-model="v.configMap.name" filterable placeholder="ConfigMap"><el-option v-for="cm in configMaps" :key="cm.name" :value="cm.name" /></el-select><el-select v-if="v.secret" v-model="v.secret.secretName" filterable placeholder="Secret"><el-option v-for="s in secrets" :key="s.name" :value="s.name" /></el-select><div v-if="v.emptyDir" class="kwe-grid"><el-select v-model="v.emptyDir.medium"><el-option value="" :label="tr('磁盘')" /><el-option value="Memory" :label="tr('内存')" /></el-select><el-input v-model="v.emptyDir.sizeLimit" placeholder="sizeLimit: 1Gi" /></div><el-input v-if="v.hostPath" v-model="v.hostPath.path" placeholder="/data/app" /><JsonField :model-value="v" required :validator="value => typeof value.name==='string'" :label="tr('完整卷配置（JSON）')" @update:model-value="pod.volumes[i]=$event" @validity="valid(`volume-${i}`,$event)" /><el-button link type="danger" @click="pod.volumes.splice(i,1)">{{ tr('删除') }}</el-button></div><el-button @click="addVolume">+ {{ tr('存储卷') }}</el-button><template v-if="draft.kind==='StatefulSet'"><el-form-item :label="tr('服务名称')" required><el-input v-model="draft.spec.serviceName" :disabled="editing" /></el-form-item><div v-for="(claim,i) in draft.spec.volumeClaimTemplates" :key="i" class="kwe-card"><div class="kwe-grid"><el-form-item :label="tr('卷声明名称')"><el-input v-model="claim.metadata.name" :disabled="editing" /></el-form-item><el-form-item label="StorageClass"><el-input v-model="claim.spec.storageClassName" :disabled="editing" /></el-form-item><el-form-item :label="tr('访问模式')"><el-select v-model="claim.spec.accessModes" multiple :disabled="editing"><el-option v-for="mode in ['ReadWriteOnce','ReadOnlyMany','ReadWriteMany','ReadWriteOncePod']" :key="mode" :value="mode" /></el-select></el-form-item><el-form-item :label="tr('存储容量')"><el-input v-model="claim.spec.resources.requests.storage" :disabled="editing" placeholder="10Gi" /></el-form-item></div><el-button link type="danger" :disabled="editing" @click="draft.spec.volumeClaimTemplates.splice(i,1)">{{ tr('删除') }}</el-button></div><el-button :disabled="editing" @click="(draft.spec.volumeClaimTemplates ||= []).push({metadata:{name:'data'},spec:{accessModes:['ReadWriteOnce'],resources:{requests:{storage:'10Gi'}}}})">+ {{ tr('卷声明模板') }}</el-button><JsonField v-model="draft.spec.volumeClaimTemplates" array :validator="value => value.every(c => c.metadata && c.spec?.resources?.requests)" :disabled="editing" :label="tr('卷声明模板（JSON，创建后只读）')" @validity="valid('claims',$event)" /></template></el-form></section>
      <section v-show="active==='scheduling'"><h3>{{ tr('调度策略') }}</h3><el-form label-position="top" :disabled="frozen"><el-form-item :label="tr('节点标签选择器')"><MapEditor v-model="pod.nodeSelector" :disabled="frozen" @validity="valid('nodeSelector',$event)" /></el-form-item><el-form-item :label="tr('污点容忍')"><Rows v-model="pod.tolerations" :disabled="frozen" :columns="[{key:'key',label:'键'},{key:'operator',label:'运算符',options:['Equal','Exists']},{key:'value',label:'值'},{key:'effect',label:'效果',options:['','NoSchedule','PreferNoSchedule','NoExecute']},{key:'tolerationSeconds',label:'容忍秒数',type:'number'}]" :create="() => ({key:'',operator:'Exists',effect:'NoSchedule'})" /></el-form-item><div class="kwe-grid"><el-form-item :label="tr('调度器')"><el-input v-model="pod.schedulerName" placeholder="default-scheduler" /></el-form-item><el-form-item label="PriorityClass"><el-input v-model="pod.priorityClassName" /></el-form-item></div><div v-for="(constraint,i) in pod.topologySpreadConstraints" :key="i" class="kwe-card"><div class="kwe-grid"><el-form-item label="maxSkew"><el-input-number v-model="constraint.maxSkew" :min="1" /></el-form-item><el-form-item label="topologyKey"><el-input v-model="constraint.topologyKey" /></el-form-item><el-form-item label="whenUnsatisfiable"><el-select v-model="constraint.whenUnsatisfiable"><el-option value="DoNotSchedule" /><el-option value="ScheduleAnyway" /></el-select></el-form-item></div><JsonField v-model="constraint.labelSelector" :label="tr('标签选择器（JSON）')" @validity="valid(`topology-selector-${i}`,$event)" /><el-button link type="danger" @click="pod.topologySpreadConstraints.splice(i,1)">{{ tr('删除') }}</el-button></div><el-button @click="(pod.topologySpreadConstraints ||= []).push({maxSkew:1,topologyKey:'kubernetes.io/hostname',whenUnsatisfiable:'DoNotSchedule',labelSelector:{matchLabels:{}}})">+ {{ tr('拓扑分布约束') }}</el-button><JsonField v-model="pod.topologySpreadConstraints" array :label="tr('拓扑分布约束（JSON）')" @validity="valid('topology',$event)" /></el-form></section>
      <section v-show="active==='affinity'"><h3>{{ tr('亲和性') }}</h3><el-form :disabled="frozen"><AffinityEditor v-model="pod.affinity" :disabled="frozen" @validity="valid('affinity',$event)" /></el-form></section>
      <section v-show="active==='strategy'"><h3>{{ tr('更新与任务策略') }}</h3><el-form label-position="top" :disabled="frozen"><template v-if="['Deployment','StatefulSet','DaemonSet'].includes(draft.kind)"><el-form-item :label="tr('更新策略')"><el-select :model-value="draft.spec[strategyKey]?.type || 'RollingUpdate'" @change="setStrategy"><el-option value="RollingUpdate" /><el-option :value="draft.kind==='Deployment' ? 'Recreate' : 'OnDelete'" /></el-select></el-form-item><div v-if="(draft.spec[strategyKey]?.type || 'RollingUpdate')==='RollingUpdate'" class="kwe-grid"><template v-if="draft.spec[strategyKey]?.rollingUpdate"><el-form-item v-for="key in draft.kind==='StatefulSet' ? ['partition'] : ['maxSurge','maxUnavailable']" :key="key" :label="key"><el-input v-if="key!=='partition'" v-model="draft.spec[strategyKey].rollingUpdate[key]" placeholder="25% / 1" /><el-input-number v-else v-model="draft.spec[strategyKey].rollingUpdate[key]" :min="0" /></el-form-item></template><el-button v-else @click="setStrategy('RollingUpdate')">{{ tr('自定义滚动参数') }}</el-button></div><div class="kwe-grid"><el-form-item label="minReadySeconds"><el-input-number v-model="draft.spec.minReadySeconds" :min="0" /></el-form-item><el-form-item label="revisionHistoryLimit"><el-input-number v-model="draft.spec.revisionHistoryLimit" :min="0" /></el-form-item><el-form-item v-if="draft.kind==='Deployment'" label="progressDeadlineSeconds"><el-input-number v-model="draft.spec.progressDeadlineSeconds" :min="1" /></el-form-item><el-form-item v-if="draft.kind==='StatefulSet'" label="podManagementPolicy"><el-select v-model="draft.spec.podManagementPolicy" :disabled="editing"><el-option value="OrderedReady" /><el-option value="Parallel" /></el-select></el-form-item></div></template><template v-else><div v-if="draft.kind==='CronJob'" class="kwe-grid"><el-form-item :label="tr('定时表达式')" required><el-input v-model="draft.spec.schedule" placeholder="0 * * * *" /></el-form-item><el-form-item :label="tr('时区')"><el-input v-model="draft.spec.timeZone" placeholder="Asia/Shanghai" /></el-form-item><el-form-item :label="tr('并发策略')"><el-select v-model="draft.spec.concurrencyPolicy"><el-option v-for="policy in ['Allow','Forbid','Replace']" :key="policy" :value="policy" /></el-select></el-form-item><el-form-item :label="tr('暂停')"><el-switch v-model="draft.spec.suspend" /></el-form-item><el-form-item v-for="key in ['successfulJobsHistoryLimit','failedJobsHistoryLimit','startingDeadlineSeconds']" :key="key" :label="key"><el-input-number v-model="draft.spec[key]" :min="0" /></el-form-item></div><div class="kwe-grid"><el-form-item v-for="key in ['parallelism','completions','backoffLimit','activeDeadlineSeconds','ttlSecondsAfterFinished']" :key="key" :label="key"><el-input-number v-model="jobSpec[key]" :min="key==='activeDeadlineSeconds' ? 1 : 0" /></el-form-item><el-form-item label="restartPolicy"><el-select v-model="pod.restartPolicy"><el-option value="Never" /><el-option value="OnFailure" /></el-select></el-form-item></div></template></el-form></section>
      <section v-show="active==='security'"><h3>{{ tr('Pod 安全配置') }}</h3><el-form label-position="top" :disabled="frozen"><div class="kwe-grid"><el-form-item label="ServiceAccount"><el-input v-model="pod.serviceAccountName" placeholder="default" /></el-form-item><el-form-item :label="tr('终止宽限时间（秒）')"><el-input-number v-model="pod.terminationGracePeriodSeconds" :min="0" /></el-form-item></div><Rows v-model="pod.imagePullSecrets" :disabled="frozen" :columns="[{key:'name',label:'镜像凭据',options:secrets.map(s => s.name)}]" :create="() => ({name:''})" /><JsonField v-model="pod.securityContext" :label="tr('Pod 安全上下文（JSON）')" @validity="valid('podSecurity',$event)" /></el-form></section>
      <section v-if="!editing" v-show="active==='access'"><h3>{{ tr('访问设置') }}</h3><el-form label-position="top" :disabled="frozen"><el-checkbox v-model="access.enabled">{{ tr('同时创建 Service') }}</el-checkbox><template v-if="access.enabled"><div class="kwe-grid"><el-form-item :label="tr('服务名称')"><el-input v-model="access.name" :placeholder="draft.metadata.name" /></el-form-item><el-form-item :label="tr('类型')"><el-select v-model="access.type"><el-option v-for="type in ['ClusterIP','NodePort','LoadBalancer']" :key="type" :value="type" /></el-select></el-form-item></div><Rows v-model="access.ports" :disabled="frozen" :columns="[{key:'name',label:'名称'},{key:'port',label:'服务端口',type:'number',min:1,max:65535},{key:'targetPort',label:'目标端口'},{key:'protocol',label:'协议',options:['TCP','UDP','SCTP']},...(access.type==='NodePort' ? [{key:'nodePort',label:'NodePort',type:'number',min:1,max:65535}] : [])]" :create="() => ({name:'',port:80,targetPort:8080,protocol:'TCP'})" /><el-checkbox v-model="access.ingress">{{ tr('同时创建 Ingress') }}</el-checkbox><template v-if="access.ingress"><el-form-item label="Ingress Class"><el-input v-model="access.className" /></el-form-item><div v-for="(rule,i) in access.rules" :key="i" class="kwe-card"><el-input v-model="rule.host" placeholder="app.example.com" /><div v-for="(path,j) in rule.http.paths" :key="j" class="kwe-card"><div class="kwe-grid"><el-form-item :label="tr('路径')"><el-input v-model="path.path" /></el-form-item><el-form-item label="pathType"><el-select v-model="path.pathType"><el-option value="Prefix" /><el-option value="Exact" /><el-option value="ImplementationSpecific" /></el-select></el-form-item><el-form-item :label="tr('服务名称')"><el-input v-model="path.backend.service.name" /></el-form-item><el-form-item :label="tr('服务端口')"><el-input-number v-model="path.backend.service.port.number" :min="1" :max="65535" /></el-form-item></div><el-button link type="danger" @click="rule.http.paths.splice(j,1)">{{ tr('删除') }}</el-button></div><el-button size="small" @click="rule.http.paths.push({path:'/',pathType:'Prefix',backend:{service:{name:access.name || draft.metadata.name,port:{number:access.ports[0]?.port || 80}}}})">+ {{ tr('路径') }}</el-button><JsonField v-model="rule.http.paths" array :validator="value => value.every(p => p.backend?.service?.port)" :label="tr('路径与服务映射（JSON）')" @validity="valid(`paths-${i}`,$event)" /><el-button link type="danger" @click="access.rules.splice(i,1)">{{ tr('删除') }}</el-button></div><el-button @click="addRule">+ {{ tr('路由规则') }}</el-button><div v-for="(tls,i) in access.tls" :key="i" class="kwe-card"><el-select v-model="tls.hosts" multiple filterable allow-create default-first-option :placeholder="tr('TLS 域名')" /><el-select v-model="tls.secretName" filterable placeholder="TLS Secret"><el-option v-for="secret in secrets" :key="secret.name" :value="secret.name" /></el-select><el-button link type="danger" @click="access.tls.splice(i,1)">{{ tr('删除') }}</el-button></div><el-button @click="access.tls.push({hosts:[],secretName:''})">+ TLS</el-button><JsonField v-model="access.tls" array :validator="value => value.every(t => Array.isArray(t.hosts))" :label="tr('TLS 配置（JSON，仅引用 Secret 名称）')" @validity="valid('tls',$event)" /></template></template></el-form></section>
      <section v-show="active==='review'"><h3>{{ tr('信息确认') }}</h3><el-descriptions :column="2" border><el-descriptions-item :label="tr('名称')">{{ draft.metadata.name || '—' }}</el-descriptions-item><el-descriptions-item :label="tr('命名空间')">{{ draft.metadata.namespace }}</el-descriptions-item><el-descriptions-item :label="tr('容器数量')">{{ pod.containers.length }} + {{ pod.initContainers?.length || 0 }} Init</el-descriptions-item><el-descriptions-item :label="tr('类型')">{{ draft.kind }}</el-descriptions-item></el-descriptions><p class="kwe-hint">{{ tr(updateImpact(draft)) }}</p><el-table v-if="editing" :data="changes" size="small"><el-table-column prop="path" :label="tr('变更字段')" min-width="200" /><el-table-column prop="before" :label="tr('修改前')" show-overflow-tooltip /><el-table-column prop="after" :label="tr('修改后')" show-overflow-tooltip /></el-table><div v-if="results" class="kwe-results"><div v-for="(result,key) in Object.fromEntries(Object.entries(results).filter(([,value]) => value?.status))" :key="key"><el-tag :type="result.status==='failed' ? 'danger' : 'success'">{{ result.status }}</el-tag> {{ key }} / {{ result.name }} <p v-if="result.error">{{ result.error }}</p></div></div><el-collapse><el-collapse-item :title="tr('资源预览（YAML）')"><pre class="kwe-preview">{{ preview }}</pre></el-collapse-item></el-collapse><el-tag v-if="validated===preview" type="success">{{ tr('服务端校验通过') }}</el-tag><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon /></section>
    </main></div>
    <footer class="kwe-footer"><span>{{ tr('提交前执行服务端校验，并检查资源版本冲突') }}</span><el-button @click="page.workloadCreateVisible=false">{{ tr('取消') }}</el-button><el-button :disabled="busy" @click="active='review';validateOnly()">{{ tr('校验配置') }}</el-button><el-button v-if="active!=='review'" type="primary" @click="active='review'">{{ tr('信息确认') }}</el-button><el-button v-else type="primary" :disabled="busy || (editing && draft.kind==='Job')" @click="submit">{{ tr(partial ? '重试失败项' : editing ? '确认更新' : '确认创建') }}</el-button></footer>
  </section>
</template>

